insert into product_faqs (id, product_code, question, answer, source) values
  ('A-AS001-1', 'A-AS001', 'Apa saja isi dalam kardus?', 'Satu kompor batik listrik ASTOETIK versi Standar, satu wajan khusus batik, kartu garansi, dan buku petunjuk penggunaan.', 'manual'),
  ('A-AS001-2', 'A-AS001', 'Berapa banyak malam yang boleh dimasukkan?', 'Masukkan malam yang sudah dipotong-potong sesuai kebutuhan, dengan berat maksimal sekitar 250 gram pada wajan batik.', 'manual'),
  ('A-AS001-3', 'A-AS001', 'Bagaimana cara mengoperasikan kompor ini?', '1) Letakkan wajan khusus membatik ke atas tungku kompor dengan posisi sempurna.
